CREATE ASYNC REPLICATION r FOR `a` AS `b` WITH (CONNECTION_STRING = 'grpc://h:2135/?database=/x', PASSWORD = 'p', USER = 'u');
CREATE ASYNC REPLICATION r2 FOR `a` AS `c` WITH (CONNECTION_STRING = 'grpc://h:2135/?database=/x', TOKEN_SECRET_NAME = 's');
ALTER ASYNC REPLICATION r SET (STATE = "DONE", FAILOVER_MODE = "FORCE");
ALTER ASYNC REPLICATION r2 SET (TOKEN = 't');
CREATE TRANSFER x FROM `topic` TO `tbl` USING ($msg) -> { $x = 1; RETURN [<|id: $x|>]; } WITH (CONNECTION_STRING = 'grpc://h', TOKEN = 'tk');
ALTER TRANSFER x SET USING ($msg) -> { RETURN [] };
ALTER TRANSFER x SET (PASSWORD = 'pw');
